/// One step of the classical 4th-order **Runge–Kutta** (RK4) method for
/// `dy/dt = f(t, y)`.
///
/// Combines four slope evaluations (`k1`..`k4`) with the Simpson-like weights
/// `(1, 2, 2, 1)/6`: local truncation error `O(h^5)`, global error `O(h^4)`.
/// The workhorse fixed-step explicit integrator.
///
/// Generated by kovan-codegen (docs/kovan.md § "Numerical Methods → ODE
/// Solvers"). Deterministic template; depends only on `core`/`std` `f64`.
pub fn rk4_step<F>(f: &F, t: f64, y: f64, h: f64) -> f64
where
    F: Fn(f64, f64) -> f64,
{
    let k1 = f(t, y);
    let k2 = f(t + 0.5 * h, y + 0.5 * h * k1);
    let k3 = f(t + 0.5 * h, y + 0.5 * h * k2);
    let k4 = f(t + h, y + h * k3);
    y + (h / 6.0) * (k1 + 2.0 * k2 + 2.0 * k3 + k4)
}

/// Integrate `dy/dt = f(t, y)` from `(t0, y0)` for `n` steps of size `h` with
/// RK4, returning the `(t, y)` trajectory (length `n + 1`, including the initial
/// point).
pub fn rk4_integrate<F>(f: F, t0: f64, y0: f64, h: f64, n: usize) -> Vec<(f64, f64)>
where
    F: Fn(f64, f64) -> f64,
{
    let mut out = Vec::with_capacity(n + 1);
    let mut t = t0;
    let mut y = y0;
    out.push((t, y));
    for _ in 0..n {
        y = rk4_step(&f, t, y, h);
        t += h;
        out.push((t, y));
    }
    out
}
